package com.portfolio.assetory.payment.controller;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import com.portfolio.assetory.global.auth.CurrentUserId;import com.portfolio.assetory.global.response.ApiResponse;import com.portfolio.assetory.payment.dto.request.MockPaymentRequest;import com.portfolio.assetory.payment.dto.response.MockPaymentResponse;import com.portfolio.assetory.payment.service.PaymentService;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/payments") public class PaymentController {private final PaymentService service;public PaymentController(PaymentService service){this.service=service;}@PostMapping("/mock") public ResponseEntity<ApiResponse<MockPaymentResponse>> execute(@CurrentUserId Long userId,@Valid @RequestBody MockPaymentRequest request){return ResponseEntity.ok(ApiResponse.success(service.execute(userId,request)));}@GetMapping("/{paymentId}")public ResponseEntity<ApiResponse<com.portfolio.assetory.payment.dto.response.PaymentResponse>> get(@CurrentUserId Long userId,@PathVariable Long paymentId){return ResponseEntity.ok(ApiResponse.success(service.get(userId,paymentId)));}}
